"""
delete_service.py - Dienst zum Löschen veralteter Datensätze aus der Datenbank.

Verwendung:
    from core_services.db import delete_old_records
    delete_old_records - Löscht aus einer tabelle alle Datensätze, deren Wert in einer
        Datumsspalte älter ist als das angegebene Stichdatum.
"""

import logging
import re
from collections.abc import Sequence
from datetime import date, datetime
from typing import Any

from ..constants import DATABASE
from .client import connect_to_db

logger = logging.getLogger(__name__)

_IDENTIFIER_RE = re.compile(r"^[a-zA-Z0-9_]+$")
DEFAULT_IMPORT_FRAGMENT_PREFIXES = ("__sqlmesh_load_", "_temp_")


def _validate_identifier(name: str, kind: str) -> str:
    """Validiert einen SQL-Bezeichner gegen SQL-Injection.

    Args:
        name: Der zu prüfende Bezeichner.
        kind: Bezeichnung für die Fehlermeldung (z. B. 'Tabellenname').

    Returns:
        Der validierte Bezeichner.

    Raises:
        ValueError: Wenn der Bezeichner ungültige Zeichen enthält.
    """
    if not isinstance(name, str) or not _IDENTIFIER_RE.match(name):
        raise ValueError(f"Ungültiger {kind}: {name!r}")
    return name


def _quote_identifier(name: str, kind: str) -> str:
    """Validiert einen SQL-Bezeichner und gibt ihn mit Backticks zurück.

    Args:
        name: Der zu prüfende Bezeichner.
        kind: Bezeichnung für die Fehlermeldung.

    Returns:
        Sicher quotierter SQL-Bezeichner.
    """
    return f"`{_validate_identifier(name, kind)}`"


def _validate_prefix(prefix: str) -> str:
    """Validiert ein Tabellenpräfix für die Fragment-Bereinigung.

    Args:
        prefix: Tabellenpräfix, das nur SQL-Bezeichner-Zeichen enthalten darf.

    Returns:
        Das validierte Präfix.

    Raises:
        ValueError: Wenn das Präfix leer ist oder ungültige Zeichen enthält.
    """
    if not prefix:
        raise ValueError("Tabellenpräfix darf nicht leer sein.")
    return _validate_identifier(prefix, "Tabellenpräfix")


def _normalize_cutoff(cutoff_date: str | date | datetime) -> str:
    """Normalisiert das Stichdatum auf einen ISO-String (YYYY-MM-DD[ HH:MM:SS]).

    Args:
        cutoff_date: Stichdatum als String, date oder datetime.

    Returns:
        ISO-formatierter String.

    Raises:
        ValueError: Wenn das Datum kein gültiges Format hat.
    """
    if isinstance(cutoff_date, datetime):
        return cutoff_date.strftime("%Y-%m-%d %H:%M:%S")
    if isinstance(cutoff_date, date):
        return cutoff_date.strftime("%Y-%m-%d")
    if isinstance(cutoff_date, str):
        # Format validieren — entweder YYYY-MM-DD oder YYYY-MM-DD HH:MM:SS
        for fmt in ("%Y-%m-%d", "%Y-%m-%d %H:%M:%S"):
            try:
                datetime.strptime(cutoff_date, fmt)
                return cutoff_date
            except ValueError:
                continue
        raise ValueError(
            f"Ungültiges Datumsformat: {cutoff_date!r}. Erwartet: 'YYYY-MM-DD' oder 'YYYY-MM-DD HH:MM:SS'."
        )
    raise TypeError(f"cutoff_date muss str, date oder datetime sein, nicht {type(cutoff_date).__name__}")


def _validate_positive_int(value: int, name: str) -> int:
    """Validiert einen positiven Integer-Wert.

    Args:
        value: Der zu prüfende Wert.
        name: Name des Parameters für die Fehlermeldung.

    Returns:
        Der validierte Integer-Wert.

    Raises:
        ValueError: Wenn der Wert kein positiver Integer ist.
    """
    if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
        raise ValueError(f"{name} muss ein positiver int sein, nicht {value!r}")
    return value


def _fetch_old_base_table_names(cursor: Any, older_than_days: int) -> list[str]:
    """Liest alte normale Tabellen aus dem aktuell verbundenen Datenbankschema.

    Args:
        cursor: MariaDB-Cursor.
        older_than_days: Mindestalter der Tabelle in Tagen.

    Returns:
        Liste der Tabellennamen ohne Views, die älter als die Grenze sind.
    """
    cursor.execute(
        f"""
        SELECT TABLE_NAME
        FROM information_schema.TABLES
        WHERE TABLE_SCHEMA = DATABASE()
          AND TABLE_TYPE = 'BASE TABLE'
          AND CREATE_TIME IS NOT NULL
          AND CREATE_TIME < DATE_SUB(NOW(), INTERVAL {older_than_days} DAY)
        ORDER BY TABLE_NAME
        """
    )
    table_names = []
    for row in cursor.fetchall():
        table_names.append(str(row[0]))
    return table_names


def delete_tables_by_prefixes(
    prefixes: Sequence[str] = DEFAULT_IMPORT_FRAGMENT_PREFIXES,
    database: str = DATABASE,
    older_than_days: int = 3,
    dry_run: bool = True,
) -> list[str]:
    """Löscht Import-Fragmenttabellen anhand erlaubter Tabellenpräfixe.

    Die Funktion ist für übrig gebliebene Import-Fragmente gedacht, z. B.
    ``__sqlmesh_load_...`` oder ``_temp_...``. Es werden nur normale Tabellen
    im aktuell verbundenen Schema berücksichtigt, deren ``CREATE_TIME`` älter
    als ``older_than_days`` Tage ist; Views bleiben unverändert.

    Args:
        prefixes: Erlaubte Tabellenpräfixe. Jedes Präfix darf nur Zeichen
            enthalten, die auch in SQL-Bezeichnern erlaubt sind.
        database: Der Name der Datenbank.
        older_than_days: Mindestalter der Tabelle in Tagen. Standard: 3.
        dry_run: Wenn True, werden passende Tabellen nur zurückgegeben und
            geloggt. Bei False werden sie per ``DROP TABLE`` gelöscht.

    Returns:
        Liste der gefundenen bzw. gelöschten Tabellen.

    Raises:
        ValueError: Bei leerer Präfixliste oder ungültigen Präfixen.
        mariadb.Error: Bei Datenbankfehlern.
    """
    if isinstance(prefixes, str):
        raise ValueError("prefixes muss eine Sequenz von Tabellenpräfixen sein, kein einzelner String.")

    validated_prefixes = tuple(_validate_prefix(prefix) for prefix in prefixes)
    if not validated_prefixes:
        raise ValueError("Mindestens ein Tabellenpräfix muss angegeben werden.")
    minimum_age_days = _validate_positive_int(older_than_days, "older_than_days")

    connection = connect_to_db(database)
    try:
        cursor = connection.cursor()
        table_names = _fetch_old_base_table_names(cursor, minimum_age_days)
        matching_tables = sorted(table_name for table_name in table_names if table_name.startswith(validated_prefixes))

        if dry_run:
            logger.info(
                "[dry_run] %s Import-Fragmenttabellen älter als %s Tage würden gelöscht: %s",
                len(matching_tables),
                minimum_age_days,
                ", ".join(matching_tables) if matching_tables else "-",
            )
            return matching_tables

        for table_name in matching_tables:
            safe_table = _quote_identifier(table_name, "Tabellenname")
            cursor.execute(f"DROP TABLE {safe_table}")
            logger.info("Import-Fragmenttabelle '%s' gelöscht.", table_name)

        connection.commit()
        logger.info("%s Import-Fragmenttabellen älter als %s Tage gelöscht.", len(matching_tables), minimum_age_days)
        return matching_tables

    except Exception as e:
        logger.error(f"Fehler beim Löschen von Import-Fragmenttabellen in '{database}': {e}", exc_info=True)
        raise
    finally:
        connection.close()


def delete_old_records(
    target_table: str,
    date_column: str,
    cutoff_date: str | date | datetime,
    database: str = DATABASE,
    batch_size: int = 10_000,
    dry_run: bool = False,
) -> int:
    """Löscht in Batches alle Datensätze einer tabelle, deren Datumsspalte vor dem Stichdatum liegt.

    Es werden alle Zeilen gelöscht, für die gilt: ``date_column < cutoff_date``.
    Zeilen mit ``NULL`` in der Datumsspalte bleiben unverändert.

    Die Löschung erfolgt iterativ per ``DELETE ... LIMIT {batch_size}`` mit Commit
    nach jedem Batch, um lange Transaktionen, große Undo-Logs und Lock-Contention
    bei Tabellen mit vielen Millionen Zeilen zu vermeiden.

    Hinweis: Für akzeptable Performance sollte auf ``date_column`` ein Index liegen.
    Ohne Index muss jeder Batch einen Tablescan durchführen, bis ``batch_size``
    Treffer gefunden sind — das skaliert bei großen Tabellen schlecht.

    Args:
        target_table: Name der tabelle, aus der gelöscht werden soll.
        date_column: Name der Spalte, die das Datum enthält.
        cutoff_date: Stichdatum — alle Datensätze mit einem älteren Datum werden
            gelöscht. Akzeptiert str ('YYYY-MM-DD' oder 'YYYY-MM-DD HH:MM:SS'),
            ``datetime.date`` oder ``datetime.datetime``.
        database: Der Name der Datenbank.
        batch_size: Anzahl der Zeilen pro DELETE-Batch. Standard: 10.000.
        dry_run: Wenn True, wird nur gezählt, wie viele Zeilen betroffen wären,
            ohne tatsächlich zu löschen.

    Returns:
        Gesamtzahl der gelöschten (bzw. bei ``dry_run`` betroffenen) Zeilen.

    Raises:
        ValueError: Bei ungültigem Tabellen-/Spaltennamen, Datumsformat oder
            nicht-positivem ``batch_size``.
        mariadb.Error: Bei Datenbankfehlern.
    """
    table = _validate_identifier(target_table, "Tabellenname")
    column = _validate_identifier(date_column, "Spaltenname")
    cutoff = _normalize_cutoff(cutoff_date)
    if not isinstance(batch_size, int) or batch_size <= 0:
        raise ValueError(f"batch_size muss ein positiver int sein, nicht {batch_size!r}")

    connection = connect_to_db(database)
    try:
        cursor = connection.cursor()

        if dry_run:
            cursor.execute(
                f"SELECT COUNT(*) FROM {table} WHERE {column} < ?",
                (cutoff,),
            )
            affected = cursor.fetchone()[0]
            logger.info(f"[dry_run] {affected} Zeilen in '{table}' wären zu löschen (Bedingung: {column} < {cutoff}).")
            return int(affected)

        logger.info(f"Starte Batch-Löschung aus '{table}' (Bedingung: {column} < {cutoff}, batch_size={batch_size}).")

        total_deleted = 0
        batch_no = 0
        delete_sql = f"DELETE FROM {table} WHERE {column} < ? LIMIT {batch_size}"

        while True:
            cursor.execute(delete_sql, (cutoff,))
            deleted = cursor.rowcount
            connection.commit()

            if deleted <= 0:
                break

            batch_no += 1
            total_deleted += deleted
            logger.info(f"Batch {batch_no}: {deleted} Zeilen aus '{table}' gelöscht (gesamt: {total_deleted}).")

            if deleted < batch_size:
                break

        logger.info(
            f"Batch-Löschung aus '{table}' abgeschlossen: {total_deleted} Zeilen in {batch_no} Batches gelöscht."
        )
        return int(total_deleted)

    except Exception as e:
        logger.error(
            f"Fehler beim Löschen aus '{target_table}' (Spalte {date_column}, Stichdatum {cutoff_date}): {e}",
            exc_info=True,
        )
        raise
    finally:
        connection.close()
